import {sparseSubjectClues} from './subject-reflection-ui.js?v=0.17.0';
import {orderReflectedPathways,reflectionProgress,subjectSuggestions} from './subject-reflection.js?v=0.17.0';
import {scorePathways,careerExamples} from './engine.js?v=0.17.0';
const h=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));

export function filterPathways(paths,occupations,{area='all',query=''}={}){
 const q=query.trim().toLowerCase();
 return paths.filter(p=>(area==='all'||p.area===area)&&(!q||[p.title,p.summary,...p.courses,...p.programs.map(x=>x.title),...p.occupations.map(c=>occupations[c]?.title||'')].join(' ').toLowerCase().includes(q)));
}
export function discoveryPage({data,occupations,sources,profile,areaFilter,query,browseAll,card,lifestyle,profileStrip,earningsIntro,reflection,subjectStrip=''}){
 const ranked=orderReflectedPathways(scorePathways(data.pathways,profile),reflection),filtered=filterPathways(ranked,occupations,{area:areaFilter,query});
 const subjectActive=!!ranked[0]?.subjectActive,startingPoints=subjectSuggestions(ranked);
 const overview=areaFilter==='all'&&!query.trim()&&!browseAll;
 const recommended=overview&&((profile.complete&&!profile.flat&&!profile.nearFlat)||subjectActive);
 const areas=`<div class="area-grid">${data.areas.map((a,i)=>`<a class="area-card ${a.color}" href="#/pathways?area=${a.id}"><span class="area-icon" aria-hidden="true">${['⌘','∿','+','✳','✎','↗'][i]}</span><h3>${h(a.title)}</h3><p>${h(a.description)}</p><small>${data.pathways.filter(p=>p.area===a.id).length} broad study pathways</small><span class="arrow" aria-hidden="true">↗</span></a>`).join('')}</div>`;
 return`<div class="wrap"><section class="page-intro"><span class="eyebrow">Explore what to study</span><h1>A few directions.<br>A lot of possibility.</h1><p class="lede">Start with one of six broad areas. Compare subjects and college routes before looking at individual professions.</p><p class="subtle">${sources.collegeRelevant} career possibilities grouped into ${data.pathways.length} study pathways. <a href="#/about?section=coverage">What’s included? ↗</a></p></section>${lifestyle}${profileStrip}${subjectStrip}${earningsIntro}${sparseSubjectClues(scorePathways(data.pathways,profile),reflection)}<div class="tools"><label style="flex:1"><span class="field-label">Search by subject or major</span><input id="path-search" type="search" value="${h(query)}" placeholder="Try biology, design, teaching…" style="width:100%"></label></div><div class="chips" aria-label="Filter by area"><button class="chip ${areaFilter==='all'?'active':''}" data-area="all" aria-pressed="${areaFilter==='all'}">All areas</button>${data.areas.map(a=>`<button class="chip ${areaFilter===a.id?'active':''}" data-area="${a.id}" aria-pressed="${areaFilter===a.id}">${h(a.title)}</button>`).join('')}</div>${recommended?`<div class="section-heading"><div><h2>${startingPoints.length===4?'Four':startingPoints.length} starting points to explore</h2><p>${subjectActive?(ranked[0].subjectDiversified?'A few pathways across both repeatedly selected study directions.':'Invitations from your current course and project choices; broad interests break ties.'):'Invitations based on broad interests.'} <strong>Basis: ${subjectActive?'current subject choices; broad interests break ties':'broad interests only'}.</strong> Every other pathway stays open.</p></div></div><div class="path-grid">${startingPoints.map(card).join('')}</div>`:''}${overview&&!recommended?'<p class="note">No ranked starting points yet: a usable interest profile or at least two directional subject answers can provide them. All areas are open to explore.</p>':''}${overview?`<div class="section-heading"><div><h2>Choose a world to explore</h2><p>Open an area to see a manageable set of related college pathways.</p></div><button class="text-link" data-browse-all>Browse all ${data.pathways.length} pathways ↗</button></div>${areas}`:`<div class="section-heading"><div><h2>${query.trim()?'Study pathways to investigate':areaFilter==='all'?'All college pathways':h(data.areas.find(a=>a.id===areaFilter)?.title)}</h2><p role="status">${filtered.length} pathways${query.trim()?' connected to your search':''}. Different majors and credentials remain separate inside each.</p></div><button class="text-link" data-area="all">Back to the six areas ↗</button></div><div class="path-grid">${filtered.map(card).join('')}</div>${!filtered.length?'<div class="empty"><h2>Try another starting point.</h2><p>Search for a broader subject or explore another area.</p></div>':''}`}${!profile.complete?'<aside class="callout"><div><h3>A little reflection can help you start.</h3><p>The optional 60-item O*NET Interest Profiler explores activities you might enjoy.</p></div><a class="button" href="#/interests">Explore my interests</a></aside>':''}</div>`;
}

export function filterPrograms(programs,{query='',group='all'}={}){
 const terms=query.trim().toLocaleLowerCase().split(/\s+/).filter(Boolean);
 return programs.filter(p=>(group==='all'||(group==='later'?p.stage==='post-professional':p.stage!=='post-professional'))&&terms.every(t=>(p.title+' '+p.cip).toLocaleLowerCase().includes(t)));
}

export function orderedPrograms(p){
 const familiar={engineering:['14.0101','14.0201','14.0501','14.0701'],'health-professional':['51.0001','51.0701','51.0601','51.0602','51.1201','51.2001','51.0401','51.0201'],'applied-technology':['15.0000','15.0403','15.0613','47.0604','48.0508'],construction:['46.0000','46.0201','46.0302','46.0503'],transport:['49.0101','49.0102','49.0309'],'human-services':['19.0101','12.0301','12.0401'],faith:['39.0201','39.0601','39.0701'],interdisciplinary:['30.0101','30.0601','30.0801','30.1601']};
 const preferred=familiar[p.id]||[],rank=x=>preferred.includes(x.cip)?preferred.indexOf(x.cip):100;
 return p.programs.slice().sort((a,b)=>rank(a)-rank(b)||a.title.localeCompare(b.title));
}

export function programChoices(p,limit=12,{programButton=()=>'',query='',group='all'}={}){
 const programs=orderedPrograms(p);
 const professional=new Set(['51.0401','51.1201','51.1701','51.2001','51.2401','22.0101']);
 const row=x=>`<div class="program"><div><strong>${h(x.title)}</strong><span>CIP ${x.cip}${professional.has(x.cip)?' · professional study; check prior education':''}</span></div><div class="program-actions"><button class="text-link" data-program-link="${x.cip}">See connections ↗</button>${programButton(p.id,x.cip)}</div></div>`;
 const matching=filterPrograms(programs,{query,group});
 const initial=matching.filter(x=>x.stage!=='post-professional'),later=matching.filter(x=>x.stage==='post-professional');
 return`<div class="program-search-tools"><label for="program-search"><span class="field-label">Search program names or CIP codes</span><input id="program-search" type="search" value="${h(query)}" placeholder="Try small engine, creative writing or 47.0606"></label><label for="program-group"><span class="field-label">Program group</span><select id="program-group">${[['all','All program categories'],['programs','Programs to investigate'],['later','Later residency & fellowship']].map(([key,label])=>`<option value="${key}" ${group===key?'selected':''}>${label}</option>`).join('')}</select></label></div><p class="subtle" role="status">${matching.length} of ${programs.length} program categories ${matching.length===1?'matches':'match'}${query.trim()?' your search':''}. Search matches program names and codes; it does not establish which credential a college offers.</p>${!matching.length?'<p class="note">No program categories match. Try a broader term or another program group.</p>':''}<p class="subtle">${initial.length} program categor${initial.length===1?'y':'ies'}${later.length?' · '+later.length+' later residency or fellowship categories kept separately':''}</p><div class="program-list">${initial.slice(0,limit).map(row).join('')}</div>${initial.length>limit?'<button class="button secondary small" data-more-programs>Show more program choices</button>':''}${later.length?`<details class="later-programs" ${query.trim()||group==='later'?'open':''}><summary>After professional qualification: ${later.length} residency & fellowship categories</summary><p>These are later specialist training. Start with the qualifying professional degree and its prerequisites; these are not first college majors.</p><div class="program-list">${later.slice(0,limit).map(row).join('')}</div>${later.length>limit?'<button class="button secondary small" data-more-programs>Show more later-training categories</button>':''}</details>`:''}`;
}

export function connectionNote(o){
 return o.connectionBasis==='editorial-bls'?'Fieldguide study connection based on BLS preparation; no direct CIP program link in this snapshot.':o.connectionBasis==='source-only'?'Source inventory only; no pathway connection established by the current policy.':'Official program-to-occupation connection; check the exact credential.';
}
export function careerPossibilities(p,occupations,{programFilter='',stageFilter='all',limit=4,occupationCard}){
 const linked=careerExamples(p,occupations,programFilter),rows=linked.filter(o=>stageFilter==='all'||o.stage===stageFilter);
 const stages=[['all','All preparation routes'],['qualifying-route','Check the qualifying program'],['further-study','Further or professional study'],['experience','Usually after related experience'],['unknown','Preparation needs investigation']];
 return`<div class="panel"><h2>One beginning, different futures.</h2><p>Start with a few examples. Open more only when useful; you do not need to select a profession.</p><div class="career-filters"><label><span class="field-label">Focus on a program category</span><select id="program-filter"><option value="">All program choices & study connections</option>${p.programs.map(x=>`<option value="${x.cip}" ${programFilter===x.cip?'selected':''}>${h(x.title)}${x.stage==='post-professional'?' · later professional training':''}</option>`).join('')}</select></label><label><span class="field-label">Preparation to keep in mind</span><select id="career-stage">${stages.map(([id,label])=>`<option value="${id}" ${stageFilter===id?'selected':''}>${label}</option>`).join('')}</select></label></div><p class="note">${h(p.caution)}</p><p class="subtle" role="status">${rows.length} possibilities${stageFilter!=='all'?' in this preparation group':''} · showing ${Math.min(rows.length,limit)}. ${p.editorialConnections?.length&&!programFilter?'Includes separately labeled Fieldguide study connections.':''}</p><div class="career-list">${rows.slice(0,limit).map(occupationCard).join('')}</div><div class="actions">${rows.length>limit?`<button class="button secondary small" data-more-careers>Show ${Math.min(20,rows.length-limit)} more possibilities</button>`:''}${limit>4?'<button class="text-link" data-fewer-careers>Return to a few examples</button>':''}</div>${!rows.length?'<p>No connections in this selected group. Try another program or preparation route.</p>':''}<p class="subtle">Official connections: <a href="https://www.onetcenter.org/crosswalks/cip/Education_CIP_to_ONET_SOC.xlsx" target="_blank" rel="noopener">O*NET education crosswalk</a>. Additional BLS-based study connections are editorial and never appear as official links under a program filter.</p></div>`;
}
export function coveragePanel(coverage){
 const c=coverage.counts;
 return`<details class="panel" id="coverage-method"><summary>College coverage: ${c.mapped} of ${c.collegeRelevant} in-scope occupations connected</summary><div class="stat-row"><div><strong>${c.mapped}</strong><span>included & grouped</span></div><div><strong>${c.unmappedRelevant}</strong><span>in-scope occupations without a pathway</span></div><div><strong>${c.sourceOnly}</strong><span>other titles retained in source lookup</span></div></div><p>${h(coverage.definition)}</p><p>${c.officialProgramLinked} occupations have an official CIP connection. ${c.editorialOnly} additional occupations have separately labeled editorial study connections based on BLS preparation. These do not create program links or qualifying credentials.</p><p>College includes certificates and associate, bachelor’s and graduate routes. Some linked occupations also have noncollege routes. Programs within a pathway can require quite different preparation; graduate, residency and experienced destinations are kept explicit.</p><p>All ${c.sourceOccupations} original titles remain searchable. An occupation outside this policy is not a finding that college cannot help with that work.</p><ul>${coverage.limitations.map(x=>'<li>'+h(x)+'</li>').join('')}</ul><p><a href="./data/coverage.json" target="_blank" rel="noopener">Inspect every occupation’s inclusion basis & pathway assignments (JSON) ↗</a></p><p><a href="${coverage.links.crosswalk}" target="_blank" rel="noopener">Official education crosswalk</a> · <a href="${coverage.links.preparation}" target="_blank" rel="noopener">BLS typical preparation</a> · <a href="${coverage.links.educationDefinitions}" target="_blank" rel="noopener">BLS education definitions</a></p></details>`;
}
